// R-19: resume files the e2e specs upload. References only: the files stay in tests/fixtures/
// (generated by tests/fixtures/make_fixtures.py, described in tests/fixtures/manifest.json).
// The demo resume (O-5: links the GitHub account the owner named) is passed with env E2E_RESUME
// (demoResumePath below) until it is checked in.
import { existsSync } from 'node:fs';
import { isAbsolute, join, resolve } from 'node:path';
import { REPO_DIR, TESTS_DIR } from '../lib/env.mjs';

const FIXTURES_DIR = join(TESTS_DIR, 'fixtures');

export const fixtures = Object.freeze({
  // f1: text-layer PDF, single column, GitHub + LinkedIn links (synthetic login example-mokafor).
  textPdf: join(FIXTURES_DIR, 'f1_dev_github.pdf'),
  // f6: image-only PDF, no text layer; the upload must end in the "unreadable" message.
  imageOnlyPdf: join(FIXTURES_DIR, 'f6_image_only.pdf'),
});

// Path of a fixture, or a clear error if it has not been generated.
export function fixturePath(name) {
  const p = fixtures[name];
  if (!p) throw new Error(`Unknown e2e fixture "${name}"; known: ${Object.keys(fixtures).join(', ')}`);
  if (!existsSync(p)) throw new Error(`Fixture missing: ${p} (regenerate with tests/fixtures/make_fixtures.py)`);
  return p;
}

// The resume the spine uploads: env E2E_RESUME (absolute, or relative to the repo root) when
// set, e.g. the real demo resume that links a live GitHub account; otherwise fixture f1.
export function demoResumePath() {
  const fromEnv = process.env.E2E_RESUME;
  if (!fromEnv) return fixturePath('textPdf');
  const p = isAbsolute(fromEnv) ? fromEnv : resolve(REPO_DIR, fromEnv);
  if (!existsSync(p)) throw new Error(`E2E_RESUME points to a file that does not exist: ${p}`);
  if (!/\.(pdf|docx)$/i.test(p)) throw new Error(`E2E_RESUME must be a .pdf or .docx file: ${p}`);
  return p;
}
